        "ko": "페를란 전망대에서는 레이캬비크를 360도로 조망할 수 있습니다. 공식 방문 안내에는 전시관 운영시간 09:00–21:00, 전망대 입장 포함, 건물 내 승강기 이용이 안내되어 있습니다. 운영시간과 입장 조건은 바뀔 수 있으니 방문 전에 확인하세요.",
        "zh": "珍珠楼环形观景台可360度俯瞰雷克雅未克。官方访客页面列出的展览开放时间为09:00–21:00，观景台包含在门票内，馆内设有电梯。开放时间和票务条件可能变化，请出行前核实。"
