        "en": "The official visitor page describes lifts and easy access to the observation deck. This is a ticketed indoor venue; confirm lift operation and the route that suits your needs.",
        "ja": "公式案内には館内のエレベーターと展望デッキへのアクセスについて記載があります。チケットが必要な屋内施設です。エレベーターの稼働や利用しやすい経路を事前にご確認ください。",
        "ko": "공식 안내는 건물 내 승강기와 전망대 접근을 설명합니다. 입장권이 필요한 실내 시설이며, 승강기 운행과 본인에게 맞는 이동 경로를 미리 확인하세요.",
        "zh": "官方访客页面介绍了电梯及观景台通行信息。这是需购票的室内场所；请提前确认电梯运行状况以及适合自己的路线。"
