        "ko": "높이 114m의 30층 전망대이며, 공식 관광 안내에는 엘리베이터 이용이 기재되어 있습니다. 운행 여부와 당일 이용 조건을 확인하세요.",
        "zh": "观景露台位于地面以上114米的30层；官方旅游信息称可乘电梯到达。请确认当天的电梯运行和入场安排。"
